// ── env serialisation ─────────────────────────────────────────────────────────
//
// HOME / OPENHUMAN_WORKSPACE / BACKEND_URL are process-global; parallel tests
// in this binary would clobber each other without a lock.

static COMPOSIO_E2E_ENV_LOCK: OnceLock<Mutex<()>> = OnceLock::new();

fn composio_e2e_env_lock() -> std::sync::MutexGuard<'static, ()> {
    let mutex = COMPOSIO_E2E_ENV_LOCK.get_or_init(|| Mutex::new(()));
    match mutex.lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    }
}

const TEST_RPC_TOKEN: &str = "composio-e2e-rpc-token";
const TEST_JWT: &str = "e2e-composio-jwt";

static RPC_AUTH_ONCE: OnceLock<()> = OnceLock::new();

fn ensure_rpc_auth() {
    RPC_AUTH_ONCE.get_or_init(|| {
        // SAFETY: set_var inside OnceLock runs exactly once, before concurrent
        // env reads — same pattern as `ensure_test_rpc_auth` in json_rpc_e2e.rs.
        unsafe { std::env::set_var(CORE_TOKEN_ENV_VAR, TEST_RPC_TOKEN) };
        let token_dir = std::env::temp_dir().join("openhuman-composio-e2e-auth");
        init_rpc_token(&token_dir).expect("init rpc token for composio_post_oauth_retry_e2e");
    });
}

// ── env-var guard ─────────────────────────────────────────────────────────────

struct EnvGuard {
    key: &'static str,
    prev: Option<String>,
}

impl EnvGuard {
    fn set_to_path(key: &'static str, path: &Path) -> Self {
        let prev = std::env::var(key).ok();
        std::env::set_var(key, path.as_os_str());
        Self { key, prev }
    }

    fn unset(key: &'static str) -> Self {
        let prev = std::env::var(key).ok();
        std::env::remove_var(key);
        Self { key, prev }
    }
}

impl Drop for EnvGuard {
    fn drop(&mut self) {
        match &self.prev {
            Some(v) => std::env::set_var(self.key, v),
            None => std::env::remove_var(self.key),
        }
    }
}

// ── mock backend builders ─────────────────────────────────────────────────────

/// Minimal mock of the openhuman backend for the composio e2e tests.
/// Handles:
///   - `GET /settings` and `GET /auth/me` — JWT validation probe issued by
///     `auth_store_session`. Returns a synthetic user object.
///   - `POST /agent-integrations/composio/execute` — sequenced responses driven
///     by `ComposioExecuteState`.
#[derive(Clone)]
struct ComposioExecuteState {
    /// Incremented on every hit to `/agent-integrations/composio/execute`.
    hit_count: Arc<AtomicUsize>,
    /// Closure returning the mock response for request number `n` (0-indexed).
    response_fn: Arc<dyn Fn(usize) -> Value + Send + Sync>,
}

impl ComposioExecuteState {
    fn new(response_fn: impl Fn(usize) -> Value + Send + Sync + 'static) -> Self {
        Self {
            hit_count: Arc::new(AtomicUsize::new(0)),
            response_fn: Arc::new(response_fn),
        }
    }
}

async fn mock_current_user(headers: HeaderMap) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let auth = headers
        .get(AUTHORIZATION)
        .and_then(|v| v.to_str().ok())
        .unwrap_or("");
    if auth != format!("Bearer {TEST_JWT}") {
        return Err((
            StatusCode::UNAUTHORIZED,
            Json(json!({ "success": false, "error": "unauthorized" })),
        ));
    }
    Ok(Json(json!({
        "success": true,
        "data": {
            "_id": "composio-e2e-user",
            "username": "composio-e2e"
        }
    })))
}

async fn mock_composio_execute(
    State(state): State<ComposioExecuteState>,
    headers: HeaderMap,
    Json(_body): Json<Value>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let auth = headers
        .get(AUTHORIZATION)
        .and_then(|v| v.to_str().ok())
        .unwrap_or("");
    if auth != format!("Bearer {TEST_JWT}") {
        return Err((
            StatusCode::UNAUTHORIZED,
            Json(json!({ "success": false, "error": "unauthorized" })),
        ));
    }
    let n = state.hit_count.fetch_add(1, Ordering::SeqCst);
    tracing::debug!(
        hit_n = n,
        "[composio-e2e-mock] /agent-integrations/composio/execute called"
    );
    Ok(Json((state.response_fn)(n)))
}

fn mock_backend_router(execute_state: ComposioExecuteState) -> Router {
    Router::new()
        .route("/settings", get(mock_current_user))
        .route("/auth/me", get(mock_current_user))
        .route(
            "/agent-integrations/composio/execute",
            post(mock_composio_execute).with_state(execute_state),
        )
}

// ── infrastructure helpers ────────────────────────────────────────────────────

async fn serve_ephemeral(app: Router) -> (SocketAddr, tokio::task::JoinHandle<()>) {
    ensure_rpc_auth();
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("bind ephemeral port");
    let addr = listener.local_addr().expect("local addr");
    let handle = tokio::spawn(async move {
        axum::serve(listener, app).await.ok();
    });
    (addr, handle)
}

fn write_test_config(openhuman_dir: &Path, api_origin: &str) {
    let cfg = format!(
        r#"api_url = "{api_origin}"
default_model = "e2e-mock-model"
default_temperature = 0.7
chat_onboarding_completed = true

[secrets]
encrypt = false
"#
    );
    fn write_cfg(dir: &Path, cfg: &str) {
        std::fs::create_dir_all(dir).expect("mkdir config dir");
        std::fs::write(dir.join("config.toml"), cfg).expect("write config.toml");
    }
    write_cfg(openhuman_dir, &cfg);
    // Pre-login user directory: config resolution uses `users/local` before an
    // active user is established (same pattern as write_min_config in
    // json_rpc_e2e.rs). Without this, auth_store_session hits the real backend.
    write_cfg(&openhuman_dir.join("users").join("local"), &cfg);
    // Post-login user-scoped directory.
    write_cfg(&openhuman_dir.join("users").join("composio-e2e-user"), &cfg);
}

async fn post_json_rpc(rpc_base: &str, id: i64, method: &str, params: Value) -> Value {
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(30))
        .build()
        .expect("reqwest client");
    let body = json!({
        "jsonrpc": "2.0",
        "id": id,
        "method": method,
        "params": params
    });
    let url = format!("{}/rpc", rpc_base.trim_end_matches('/'));
    let resp = client
        .post(&url)
        .header(AUTHORIZATION, format!("Bearer {TEST_RPC_TOKEN}"))
        .json(&body)
        .send()
        .await
        .unwrap_or_else(|e| panic!("POST {url}: {e}"));
    assert!(
        resp.status().is_success(),
        "HTTP error {} calling {method}",
        resp.status()
    );
    resp.json::<Value>()
        .await
        .unwrap_or_else(|e| panic!("json parse for {method}: {e}"))
}

fn assert_no_jsonrpc_error<'a>(v: &'a Value, ctx: &str) -> &'a Value {
    if let Some(err) = v.get("error") {
        panic!("{ctx}: unexpected JSON-RPC error: {err}");
    }
    v.get("result")
        .unwrap_or_else(|| panic!("{ctx}: missing result field: {v}"))
}

// ── test: happy-path retry ────────────────────────────────────────────────────

/// Flow 1 from the task brief:
///
/// After completing Composio OAuth the user immediately invokes an action.
/// The first backend call returns the post-OAuth gappy auth-error payload
/// (`successful=false, error="Connection error, try to authenticate"`).
/// The retry layer should fire automatically and the second backend call
/// should return real data. The RPC result observed by the caller must be
/// `successful=true` with the action data — the transient error is invisible.
///
/// The test drives this through the full `openhuman.composio_execute` RPC
/// handler so the retry logic in `execute_with_auth_retry_inner` and
/// `execute_tool_with_post_oauth_retry` is exercised end-to-end.
#[tokio::test]
async fn post_oauth_gap_retries_and_returns_real_data() {
    let _env_lock = composio_e2e_env_lock();

    let tmp = tempdir().expect("tempdir");
    let home = tmp.path();
    let openhuman_home = home.join(".openhuman");

    let _home_guard = EnvGuard::set_to_path("HOME", home);
    let _ws_guard = EnvGuard::unset("OPENHUMAN_WORKSPACE");
    let _backend_url_guard = EnvGuard::unset("BACKEND_URL");
    let _vite_guard = EnvGuard::unset("VITE_BACKEND_URL");

    // Sequence: call 0 → post-OAuth gap error; call 1+ → success.
    let execute_state = ComposioExecuteState::new(|n| {
        if n == 0 {
            // Simulates Composio's transient readiness-gap response.
            json!({
                "success": true,
                "data": {
                    "data": {},
                    "successful": false,
                    "error": "Connection error, try to authenticate",
                    "costUsd": 0.0
                }
            })
        } else {
            // Simulates the real action response after the gateway has synced.
            json!({
                "success": true,
                "data": {
                    "data": { "events": [{ "id": "evt_1", "summary": "Team standup" }] },
                    "successful": true,
                    "error": null,
                    "costUsd": 0.0018
                }
            })
        }
    });

    let hit_count = execute_state.hit_count.clone();

    let (mock_addr, mock_join) = serve_ephemeral(mock_backend_router(execute_state)).await;
    let mock_origin = format!("http://{mock_addr}");
    write_test_config(&openhuman_home, &mock_origin);

    let (rpc_addr, rpc_join) = serve_ephemeral(build_core_http_router(false)).await;
    let rpc_base = format!("http://{rpc_addr}");

    tokio::time::sleep(Duration::from_millis(100)).await;

    // Authenticate with the core RPC server so backend calls carry a valid JWT.
    let store = post_json_rpc(
        &rpc_base,
        1,
        "openhuman.auth_store_session",
        json!({ "token": TEST_JWT, "user_id": "composio-e2e-user" }),
    )
    .await;
    assert_no_jsonrpc_error(&store, "auth_store_session");

    // Invoke `composio_execute` over JSON-RPC — the same surface the UI calls.
    // The `execute_dispatch` → `auth_retry` → `client` chain will fire the
    // first call, see the gappy auth error, back off (zero-delay in tests
    // because `AUTH_RETRY_BACKOFF` is 8 s but the inner mock is synchronous),
    // and retry.
    let exec = post_json_rpc(
        &rpc_base,
        2,
        "openhuman.composio_execute",
        json!({
            "tool": "GOOGLECALENDAR_EVENTS_LIST",
            "arguments": {}
        }),
    )
    .await;

    let envelope = assert_no_jsonrpc_error(&exec, "composio_execute");
    // RpcOutcome serialises as {"result": <ComposioExecuteResponse>, "logs": [...]}
    // when logs are present.  Unwrap one level to reach the composio payload.
    let result = envelope.get("result").unwrap_or(envelope);

    // The RPC result must surface the second (successful) backend response.
    assert!(
        result
            .get("successful")
            .and_then(Value::as_bool)
            .unwrap_or(false),
        "composio_execute must return successful=true after retrying the post-OAuth gap error; \
         got: {result}"
    );
    assert!(
        result.get("error").is_none() || result["error"].is_null(),
        "composio_execute must not surface the transient auth error; got: {result}"
    );

    // The action data from the second call must be present.
    let events = result
        .pointer("/data/events")
        .and_then(Value::as_array)
        .expect("result.data.events must be an array");
    assert_eq!(events.len(), 1, "expected one mocked event");
    assert_eq!(
        events[0]["summary"],
        json!("Team standup"),
        "event summary must match mock data"
    );

    // At least 2 backend hits: the initial gappy call + at least one retry.
    // (Could be up to 4 due to the two-layer retry stack documented in the
    // `auth_retry_tests.rs` TODO.)
    let hits = hit_count.load(Ordering::SeqCst);
    assert!(
        hits >= 2,
        "expected at least 2 backend hits (initial + retry); got {hits}"
    );
    assert!(
        hits <= 4,
        "expected at most 4 backend hits (bounded retry contract); got {hits}"
    );

    mock_join.abort();
    rpc_join.abort();
}

// ── test: real revoked-token error surfaces immediately ───────────────────────

/// Flow 2 from the task brief:
///
/// A real revoked-token / invalid-grant error is NOT in the retryable-error
/// allow-list (`POST_OAUTH_AUTH_ERROR_STRINGS`). The retry layer must surface
/// it immediately after a single backend call — no 8-second wait, no misleading
/// "try to authenticate" loop.
///
/// The assertion verifies:
///   - the RPC result carries `successful=false` with the error text preserved
///     (possibly wrapped by `format_provider_error`)
///   - the backend was hit exactly once (or up to 2 due to any unrelated inner
///     retry layer, but never more — the outer auth_retry.rs layer must not fire)
#[tokio::test]
async fn revoked_token_surfaces_without_retry() {
    let _env_lock = composio_e2e_env_lock();

    let tmp = tempdir().expect("tempdir");
    let home = tmp.path();
    let openhuman_home = home.join(".openhuman");

    let _home_guard = EnvGuard::set_to_path("HOME", home);
    let _ws_guard = EnvGuard::unset("OPENHUMAN_WORKSPACE");
    let _backend_url_guard = EnvGuard::unset("BACKEND_URL");
    let _vite_guard = EnvGuard::unset("VITE_BACKEND_URL");

    // Always return a real revoked-token error — should not be retried.
    let execute_state = ComposioExecuteState::new(|_n| {
        json!({
            "success": true,
            "data": {
                "data": {},
                "successful": false,
                "error": "invalid_grant: refresh token revoked",
                "costUsd": 0.0
            }
        })
    });

    let hit_count = execute_state.hit_count.clone();

    let (mock_addr, mock_join) = serve_ephemeral(mock_backend_router(execute_state)).await;
    let mock_origin = format!("http://{mock_addr}");
    write_test_config(&openhuman_home, &mock_origin);

    let (rpc_addr, rpc_join) = serve_ephemeral(build_core_http_router(false)).await;
    let rpc_base = format!("http://{rpc_addr}");

    tokio::time::sleep(Duration::from_millis(100)).await;

    let store = post_json_rpc(
        &rpc_base,
        1,
        "openhuman.auth_store_session",
        json!({ "token": TEST_JWT, "user_id": "composio-e2e-user" }),
    )
    .await;
    assert_no_jsonrpc_error(&store, "auth_store_session");

    let exec = post_json_rpc(
        &rpc_base,
        2,
        "openhuman.composio_execute",
        json!({
            "tool": "GMAIL_SEND_EMAIL",
            "arguments": { "to": "test@example.com", "subject": "hi", "body": "hello" }
        }),
    )
    .await;

    // The RPC layer returns a result (not a JSON-RPC error) with successful=false
    // because `execute_composio_action_kind` converts op-level errors to
    // formatted strings inside `ComposioExecuteResponse`. Either a result with
    // successful=false or a JSON-RPC error with the text is acceptable.
    let has_rpc_error = exec.get("error").is_some();
    let result_opt = exec.get("result");

    if has_rpc_error {
        // The error message must contain the revoked-token text (possibly
        // wrapped in the `[composio:error:auth]` prefix by format_provider_error).
        let err_msg = exec["error"]["message"]
            .as_str()
            .or_else(|| exec["error"].as_str())
            .unwrap_or("");
        assert!(
            err_msg.contains("revoked")
                || err_msg.contains("invalid_grant")
                || err_msg.contains("composio"),
            "RPC error should reference the revoked-token message; got: {err_msg}"
        );
    } else {
        let envelope = result_opt.expect("expected result or error");
        // RpcOutcome wraps the composio payload under a "result" key when logs
        // are present; fall back to the envelope itself for the no-logs case.
        let result = envelope.get("result").unwrap_or(envelope);
        let successful = result
            .get("successful")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        assert!(
            !successful,
            "revoked-token error must NOT be reported as successful; got: {result}"
        );
        let error_text = result.get("error").and_then(Value::as_str).unwrap_or("");
        assert!(
            error_text.contains("revoked")
                || error_text.contains("invalid_grant")
                || error_text.contains("composio"),
            "error text must reference the revoked-token or composio error; got: {error_text:?}"
        );
    }

    // The outer auth_retry.rs layer must NOT have fired — the error is not
    // in `POST_OAUTH_AUTH_ERROR_STRINGS`. We allow at most 2 hits to account
    // for the inner `execute_tool_with_post_oauth_retry` which also checks
    // the same predicate (and correctly short-circuits for this error string),
    // but in practice both layers skip the retry for non-allowlisted errors
    // so exactly 1 hit is expected.
    let hits = hit_count.load(Ordering::SeqCst);
    assert!(
        hits <= 2,
        "revoked-token error must not trigger the outer auth retry; \
         expected ≤ 2 backend hits, got {hits}"
    );
    assert!(
        hits >= 1,
        "at least one backend hit is required; got {hits}"
    );

    mock_join.abort();
    rpc_join.abort();
}

//! Tests for the post-OAuth auth-error retry in [`super`].
//!
//! These spin up a tiny axum backend that mimics Composio's
//! `/agent-integrations/composio/execute` route. Each test wires a
//! response sequence keyed by the request counter so we can assert
//! exactly how many times the gateway was hit. The backoff between
//! attempts is passed in as `Duration::from_millis(0)` so the suite
//! never sleeps for real seconds.

use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::time::Duration;

use axum::{routing::post, Json, Router};
use serde_json::{json, Value};

use super::*;
use crate::openhuman::integrations::IntegrationClient;

async fn start_mock_backend(app: Router) -> String {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();
    tokio::spawn(async move {
        axum::serve(listener, app).await.unwrap();
    });
    format!("http://127.0.0.1:{}", addr.port())
}

fn build_client_for(base_url: String) -> ComposioClient {
    let inner = Arc::new(IntegrationClient::new(base_url, "test-token".into()));
    ComposioClient::new(inner)
}

/// First call returns the post-OAuth auth-error payload; second call
/// returns a normal success. Helper must hit the backend twice and
/// surface the second response.
#[tokio::test]
async fn retries_once_on_post_oauth_auth_error_then_succeeds() {
    let counter = Arc::new(AtomicUsize::new(0));
    let counter_handler = counter.clone();
    let app = Router::new().route(
        "/agent-integrations/composio/execute",
        post(move |Json(_body): Json<Value>| {
            let counter = counter_handler.clone();
            async move {
                let n = counter.fetch_add(1, Ordering::SeqCst);
                if n == 0 {
                    Json(json!({
                        "success": true,
                        "data": {
                            "data": {},
                            "successful": false,
                            "error": "Connection error, try to authenticate",
                            "costUsd": 0.0
                        }
                    }))
                } else {
                    Json(json!({
                        "success": true,
                        "data": {
                            "data": { "ok": true },
                            "successful": true,
                            "error": null,
                            "costUsd": 0.0012
                        }
                    }))
                }
            }
        }),
    );
    let base = start_mock_backend(app).await;
    let client = build_client_for(base);

    let resp = execute_with_auth_retry_inner(
        &client,
        "GOOGLECALENDAR_EVENTS_LIST",
        Some(json!({})),
        Duration::from_millis(0),
    )
    .await
    .expect("retry path must surface a response");

    assert!(resp.successful, "second attempt should report success");
    assert_eq!(resp.data["ok"], true);
    assert_eq!(
        counter.load(Ordering::SeqCst),
        2,
        "gateway should be hit exactly twice"
    );
}

/// A real authentication failure (revoked token, mis-scoped connection,
/// …) returns a 401-equivalent payload that does **not** match the
/// post-OAuth gap string. The helper must surface it after exactly one
/// attempt so the user sees the error without a needless 8s wait.
#[tokio::test]
async fn does_not_retry_on_unrelated_error_payload() {
    let counter = Arc::new(AtomicUsize::new(0));
    let counter_handler = counter.clone();
    let app = Router::new().route(
        "/agent-integrations/composio/execute",
        post(move |Json(_body): Json<Value>| {
            let counter = counter_handler.clone();
            async move {
                counter.fetch_add(1, Ordering::SeqCst);
                Json(json!({
                    "success": true,
                    "data": {
                        "data": {},
                        "successful": false,
                        "error": "invalid_grant: refresh token revoked",
                        "costUsd": 0.0
                    }
                }))
            }
        }),
    );
    let base = start_mock_backend(app).await;
    let client = build_client_for(base);

    let resp = execute_with_auth_retry_inner(
        &client,
        "GMAIL_SEND_EMAIL",
        Some(json!({"to": "a@b.com"})),
        Duration::from_millis(0),
    )
    .await
    .expect("non-retryable payload must still resolve cleanly");

    assert!(!resp.successful);
    assert_eq!(
        resp.error.as_deref(),
        Some("invalid_grant: refresh token revoked")
    );
    assert_eq!(
        counter.load(Ordering::SeqCst),
        1,
        "non-retryable errors must not trigger a second attempt"
    );
}

/// Successful first attempt must short-circuit before the sleep — no
/// retry, no wasted round-trip.
#[tokio::test]
async fn does_not_retry_on_first_attempt_success() {
    let counter = Arc::new(AtomicUsize::new(0));
    let counter_handler = counter.clone();
    let app = Router::new().route(
        "/agent-integrations/composio/execute",
        post(move |Json(_body): Json<Value>| {
            let counter = counter_handler.clone();
            async move {
                counter.fetch_add(1, Ordering::SeqCst);
                Json(json!({
                    "success": true,
                    "data": {
                        "data": { "echoed": true },
                        "successful": true,
                        "error": null,
                        "costUsd": 0.0
                    }
                }))
            }
        }),
    );
    let base = start_mock_backend(app).await;
    let client = build_client_for(base);

    let resp = execute_with_auth_retry_inner(
        &client,
        "GITHUB_USERS_GET_AUTHENTICATED",
        None,
        Duration::from_secs(60), // would hang the test if we ever slept
    )
    .await
    .unwrap();

    assert!(resp.successful);
    assert_eq!(counter.load(Ordering::SeqCst), 1);
}

/// If Composio still returns the auth-error payload on the second call
/// (gateway not actually recovered, or real credential problem
/// masquerading as the post-OAuth string), surface the second response
/// verbatim — bounded retries, never a loop.
///
/// **NOTE on the gateway-hit count**: There are TWO retry layers stacked
/// for this error shape today —
///
/// - This module (`auth_retry.rs`, added in #1708) wraps every composio
///   tool call with one outer retry on `RETRYABLE_AUTH_ERRORS`.
/// - `ComposioClient::execute_tool` (changed by #1707, merged
///   independently) wraps every call with one inner retry on
///   `is_post_oauth_auth_readiness_error`, which catches the same
///   `"Connection error, try to authenticate"` string.
///
/// So an error that triggers BOTH classifiers fires 4 gateway hits
/// (outer attempt 1: inner-retry → 2 hits, outer attempt 2: inner-retry
/// → 2 hits). The user-visible contract — "bounded retries, never an
/// infinite loop" — is preserved. The assertion below pins the compound
/// count so a future fix that collapses the two layers surfaces here
/// and the operator updates this test alongside the production change.
///
/// TODO(composio-retry-dedup): collapse the two retry layers — see
/// `auth_retry.rs` doc-comment vs `client.rs::execute_tool_with_post_oauth_retry`.
#[tokio::test]
async fn retries_once_only_even_when_second_call_still_errors() {
    let counter = Arc::new(AtomicUsize::new(0));
    let counter_handler = counter.clone();
    let app = Router::new().route(
        "/agent-integrations/composio/execute",
        post(move |Json(_body): Json<Value>| {
            let counter = counter_handler.clone();
            async move {
                counter.fetch_add(1, Ordering::SeqCst);
                Json(json!({
                    "success": true,
                    "data": {
                        "data": {},
                        "successful": false,
                        "error": "Connection error, try to authenticate",
                        "costUsd": 0.0
                    }
                }))
            }
        }),
    );
    let base = start_mock_backend(app).await;
    let client = build_client_for(base);

    let resp =
        execute_with_auth_retry_inner(&client, "NOTION_PAGES_LIST", None, Duration::from_millis(0))
            .await
            .unwrap();

    assert!(!resp.successful);
    assert_eq!(
        resp.error.as_deref(),
        Some("Connection error, try to authenticate")
    );
    // Bounded-retry contract: at least 2 hits (outer caught + retried once)
    // and at most 4 (outer × inner double-layer compound). Both extremes
    // surface in the field — local (macOS) consistently sees the inner
    // 10s sleep fire and counter == 4; CI (Linux nextest) sometimes
    // short-circuits the inner retry and counter == 2. Either way the
    // user-visible contract holds: never an infinite loop.
    //
    // TODO(composio-retry-dedup): collapse the two retry layers — see
    // `auth_retry.rs` doc-comment vs `client.rs::execute_tool_with_post_oauth_retry`.
    // Once collapsed, tighten this to `assert_eq!(counter, 2)`.
    let hits = counter.load(Ordering::SeqCst);
    assert!(
        (2..=4).contains(&hits),
        "compound retry must be bounded: got {hits} gateway hits, expected 2-4 \
         (2 = single-layer, 4 = outer auth_retry.rs #1708 × inner execute_tool_with_post_oauth_retry #1707). \
         A count outside this range means an unintended retry loop."
    );
}

//! Smart-mock test support for the agent harness.
//!
//! This module provides a reusable "fake LLM" that drives the real
//! [`run_tool_call_loop`] without needing any network access. Two
//! building blocks are exposed:
//!
//! 1. [`KeywordScriptedProvider`] — a [`Provider`] implementation that
//!    inspects the latest `user` message of the conversation and emits
//!    canned tool calls (or a final reply) when a configured keyword
//!    matches. The first turn that has *no* matching rule returns a
//!    plain "done" reply, which terminates the loop deterministically.
//!
//!    Compared to the hand-rolled `ScriptedProvider` in
//!    [`super::tool_loop_tests`], this provider:
//!      * Reacts to the rolling conversation state instead of replaying
//!        a fixed queue — so tests can exercise iterative loops where
//!        what the LLM does next depends on what tools returned.
//!      * Supports both **native** OpenAI-style `tool_calls` and
//!        **prompt-guided** `<tool_call>…</tool_call>` text — flipping
//!        a single flag toggles which surface the harness exercises.
//!      * Records the messages it saw and the responses it returned for
//!        post-hoc assertion.
//!
//! 2. [`spawn_fake_composio_backend`] — boots a minimal axum app that
//!    responds to the `/agent-integrations/composio/*` routes with
//!    realistic-looking fixture data (real-world toolkit/action shapes,
//!    not synthetic gibberish). Tests can pair this with a
//!    [`crate::openhuman::composio::ComposioClient`] to exercise the
//!    full agent → tool → backend → response flow against a hermetic
//!    in-process server.
//!
//! Both helpers are `#[cfg(test)]`-only so they never leak into release
//! binaries.

use std::collections::VecDeque;
use std::sync::Arc;

use async_trait::async_trait;
use parking_lot::Mutex;
use serde_json::json;

use crate::openhuman::inference::provider::traits::ProviderCapabilities;
use crate::openhuman::inference::provider::{
    ChatMessage, ChatRequest, ChatResponse, Provider, ToolCall,
};

/// One scripted reaction the [`KeywordScriptedProvider`] can emit when
/// it sees its keyword in the latest user/tool turn.
#[derive(Debug, Clone)]
pub struct KeywordRule {
    /// Substring matched (case-insensitive) against the latest user
    /// or tool message in the conversation.
    pub keyword: String,
    /// Tool calls to emit. Empty ⇒ no tool calls, only `final_text`.
    pub tool_calls: Vec<ScriptedToolCall>,
    /// Optional plain-text body to include alongside any tool calls.
    /// When `tool_calls` is empty, this becomes the loop-terminating
    /// final response.
    pub final_text: Option<String>,
    /// How many times this rule may fire. `None` ⇒ unlimited.
    pub max_fires: Option<usize>,
}

#[derive(Debug, Clone)]
pub struct ScriptedToolCall {
    pub name: String,
    pub arguments: serde_json::Value,
}

impl ScriptedToolCall {
    pub fn new(name: impl Into<String>, arguments: serde_json::Value) -> Self {
        Self {
            name: name.into(),
            arguments,
        }
    }
}

impl KeywordRule {
    pub fn final_reply(keyword: impl Into<String>, text: impl Into<String>) -> Self {
        Self {
            keyword: keyword.into(),
            tool_calls: Vec::new(),
            final_text: Some(text.into()),
            max_fires: None,
        }
    }

    pub fn tool_call(keyword: impl Into<String>, call: ScriptedToolCall) -> Self {
        Self {
            keyword: keyword.into(),
            tool_calls: vec![call],
            final_text: None,
            max_fires: Some(1),
        }
    }

    pub fn with_text(mut self, text: impl Into<String>) -> Self {
        self.final_text = Some(text.into());
        self
    }

    pub fn unlimited(mut self) -> Self {
        self.max_fires = None;
        self
    }
}

/// Snapshot of one turn the provider served — handy for tests that
/// want to assert what the LLM "saw" without coupling to the harness
/// internals.
#[derive(Debug, Clone)]
pub struct ProviderTurn {
    pub messages: Vec<ChatMessage>,
    pub rule_keyword: Option<String>,
    pub emitted_tool_calls: Vec<ToolCall>,
    pub emitted_text: Option<String>,
}

struct ProviderState {
    rules: Vec<KeywordRule>,
    fired: Vec<usize>,
    turns: Vec<ProviderTurn>,
    fallback_text: String,
    next_call_id: usize,
    /// Optional queue of scripted responses to consume *before* the
    /// keyword rules run — useful when a test wants the first turn to
    /// behave deterministically regardless of the user message.
    forced: VecDeque<ChatResponse>,
}

/// Smart provider that reacts to conversation state via keyword rules.
pub struct KeywordScriptedProvider {
    state: Arc<Mutex<ProviderState>>,
    native_tools: bool,
    vision: bool,
}

impl KeywordScriptedProvider {
    pub fn new(rules: Vec<KeywordRule>) -> Self {
        Self {
            state: Arc::new(Mutex::new(ProviderState {
                rules,
                fired: Vec::new(),
                turns: Vec::new(),
                fallback_text: "done".to_string(),
                next_call_id: 0,
                forced: VecDeque::new(),
            })),
            native_tools: false,
            vision: false,
        }
    }

    pub fn with_native_tools(mut self, enabled: bool) -> Self {
        self.native_tools = enabled;
        self
    }

    pub fn with_vision(mut self, enabled: bool) -> Self {
        self.vision = enabled;
        self
    }

    pub fn with_fallback(self, text: impl Into<String>) -> Self {
        {
            let mut guard = self.state.lock();
            guard.fallback_text = text.into();
        }
        self
    }

    pub fn push_forced_response(&self, resp: ChatResponse) {
        self.state.lock().forced.push_back(resp);
    }

    pub fn turns(&self) -> Vec<ProviderTurn> {
        self.state.lock().turns.clone()
    }

    pub fn turn_count(&self) -> usize {
        self.state.lock().turns.len()
    }
}

fn latest_user_or_tool_msg(messages: &[ChatMessage]) -> Option<&ChatMessage> {
    messages
        .iter()
        .rev()
        .find(|m| m.role == "user" || m.role == "tool")
}

#[async_trait]
impl Provider for KeywordScriptedProvider {
    fn capabilities(&self) -> ProviderCapabilities {
        ProviderCapabilities {
            native_tool_calling: self.native_tools,
            vision: self.vision,
        }
    }

    async fn chat_with_system(
        &self,
        _system_prompt: Option<&str>,
        _message: &str,
        _model: &str,
        _temperature: f64,
    ) -> anyhow::Result<String> {
        Ok("fallback".into())
    }

    async fn chat(
        &self,
        request: ChatRequest<'_>,
        _model: &str,
        _temperature: f64,
    ) -> anyhow::Result<ChatResponse> {
        let messages = request.messages.to_vec();
        let mut state = self.state.lock();

        // Forced queue wins, regardless of keyword matching.
        if let Some(resp) = state.forced.pop_front() {
            state.turns.push(ProviderTurn {
                messages,
                rule_keyword: None,
                emitted_tool_calls: resp.tool_calls.clone(),
                emitted_text: resp.text.clone(),
            });
            return Ok(resp);
        }

        let probe = latest_user_or_tool_msg(&messages)
            .map(|m| m.content.to_lowercase())
            .unwrap_or_default();

        let mut chosen: Option<usize> = None;
        for (idx, rule) in state.rules.iter().enumerate() {
            let fired = *state.fired.get(idx).unwrap_or(&0);
            if let Some(cap) = rule.max_fires {
                if fired >= cap {
                    continue;
                }
            }
            if probe.contains(&rule.keyword.to_lowercase()) {
                chosen = Some(idx);
                break;
            }
        }

        let (rule_keyword, tool_calls, text) = if let Some(idx) = chosen {
            while state.fired.len() <= idx {
                state.fired.push(0);
            }
            state.fired[idx] += 1;
            let rule = state.rules[idx].clone();
            let tool_calls: Vec<ToolCall> = if self.native_tools {
                rule.tool_calls
                    .iter()
                    .map(|c| {
                        let id = state.next_call_id;
                        state.next_call_id += 1;
                        ToolCall {
                            id: format!("call_{id}"),
                            name: c.name.clone(),
                            arguments: c.arguments.to_string(),
                        }
                    })
                    .collect()
            } else {
                Vec::new()
            };

            let text = if self.native_tools {
                rule.final_text.clone()
            } else if !rule.tool_calls.is_empty() {
                // Prompt-guided: emit XML-wrapped tool calls in text.
                let mut body = String::new();
                if let Some(prefix) = &rule.final_text {
                    body.push_str(prefix);
                    if !prefix.ends_with('\n') {
                        body.push('\n');
                    }
                }
                for c in &rule.tool_calls {
                    body.push_str("<tool_call>");
                    body.push_str(&json!({"name": c.name, "arguments": c.arguments}).to_string());
                    body.push_str("</tool_call>\n");
                }
                Some(body)
            } else {
                rule.final_text.clone()
            };

            (Some(rule.keyword.clone()), tool_calls, text)
        } else {
            // No rule matched — emit the fallback as the final reply
            // so the loop terminates rather than hanging.
            (None, Vec::new(), Some(state.fallback_text.clone()))
        };

        let resp = ChatResponse {
            text: text.clone(),
            tool_calls: tool_calls.clone(),
            usage: None,
        };

        state.turns.push(ProviderTurn {
            messages,
            rule_keyword,
            emitted_tool_calls: tool_calls,
            emitted_text: text,
        });

        Ok(resp)
    }
}

